            raise ValueError('payment amount must be a nonnegative number')
        if wages not in (True, False, None) or domestic not in (True, False, None):
            raise ValueError('payment classifications must be boolean or null')
        if payer == person and py in totals:
            if domestic is True or wages is False:
                pass
            elif domestic is None or wages is None:
                unresolved = True
            else:
                totals[py] = totals[py] + amount
