    deaths = inputs['death_events']; ds = inputs['death_events_status']; marriages = inputs['marriages']; ms = inputs['marriages_status']
    if not isinstance(taxpayer, str) or not taxpayer or not isinstance(decedent, str) or not decedent or taxpayer == decedent:
