    query_year = calendar_year(begin)
    if not isinstance(deaths, list) or not isinstance(marriages, list):
        raise TypeError('fact channels must be arrays')
    if ds not in ('complete', 'incomplete') or ms not in ('complete', 'incomplete'):
        raise ValueError('invalid completion status')
    target_death = None
    for d in deaths:
        if not isinstance(d, dict):
            raise TypeError('death-event members must be objects')
        who = d['decedent_id']; day = d['death_date']
        if not isinstance(who, str):
            raise TypeError('decedent identity must be a string')
        calendar_year(day)
        if who == decedent:
            if target_death is not None:
                raise ValueError('the queried decedent has multiple death records')
            target_death = day
    for m in marriages:
        if not isinstance(m, dict):
            raise TypeError('marriage members must be objects')
        a = m['party1_id']; b = m['party2_id']; start = m['start_date']; end = m['end_date']
        if not isinstance(a, str) or not isinstance(b, str) or a == b:
            raise ValueError('marriage parties must be distinct strings')
        calendar_year(start)
        if end is not None:
            calendar_year(end)
            if end < start:
                raise ValueError('marriage interval ends before it begins')
    if target_death is None:
        if ds == 'complete':
            return {'handled': True, 'answer': 'Contradiction'}
        return {'handled': False, 'answer': None}
    death_year = calendar_year(target_death)
    if death_year not in (query_year - 1, query_year - 2):
        return {'handled': True, 'answer': 'Contradiction'}
    for m in marriages:
        a = m['party1_id']; b = m['party2_id']; start = m['start_date']; end = m['end_date']
        joined = (a == taxpayer and b == decedent) or (a == decedent and b == taxpayer)
        if joined and start <= target_death and (end is None or target_death <= end):
            return {'handled': True, 'answer': 'Entailment'}
    if ms == 'complete':
        return {'handled': True, 'answer': 'Contradiction'}
    return {'handled': False, 'answer': None}

